 "content": "def transform(grid):
    """Build the expanding V of 2s, then fill diagonals of 1s at the same slope."""
    n = len(grid[0])
    center = next((i for i, value in enumerate(grid[0]) if value == 2), n // 2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        if r <= center:
            for c in (center-r, center+r):
                if 0 <= c < n:
                    out[r][c] = 2
    # Repeat the marker's diagonal phase every four cells, avoiding the 2 outline.
    for r in range(n):
        for c in range(n):
            if (c - r - center) % 4 == 0 and out[r][c] == 0:
                out[r][c] = 1
    return out

if __name__ == '__main__':
    test = [[0] * 8 + [2] + [0] * 8]
    result = transform(test)
